def departments_to_groups(apps, schema_editor):
    """v8 sent messages to departments; turn each used department into a real group with its members."""
    Group, GroupMessage = apps.get_model("portal", "Group"), apps.get_model("portal", "GroupMessage")
    Employee = apps.get_model("portal", "Employee")
    for dept_id in GroupMessage.objects.filter(group__isnull=True, department__isnull=False).values_list(
            "department_id", flat=True).distinct():
        msg = GroupMessage.objects.filter(department_id=dept_id).first()
        g, _ = Group.objects.get_or_create(name=msg.department.name)
        g.members.set(Employee.objects.filter(department_id=dept_id).exclude(role="admin"))
        GroupMessage.objects.filter(department_id=dept_id, group__isnull=True).update(group=g)


